  (8, 'Keyboard Shortcuts', 'medium', 'If you pressed Ctrl + Z (Undo) by mistake and want your change back, which shortcut performs REDO?', 'Ctrl + W', 'Ctrl + E', 'Ctrl + Y', 'Ctrl + R', 'c'),
  (8, 'Keyboard Shortcuts', 'medium', 'Which keyboard shortcut lets you quickly switch between open apps/windows on Windows?', 'Ctrl + P', 'Shift + Enter', 'Alt + Tab', 'Ctrl + C', 'c'),
  (8, 'Keyboard Shortcuts', 'medium', 'To type a single capital letter or the "@" symbol above the number 2 without turning on Caps Lock, which key do you hold?', 'Ctrl', 'Shift', 'Tab', 'Alt', 'b'),
  (8, 'Keyboard Shortcuts', 'medium', 'Which shortcut opens a brand-new blank document or window in most apps?', 'Ctrl + M', 'Ctrl + N', 'Ctrl + B', 'Ctrl + D', 'b'),
  (8, 'Keyboard Shortcuts', 'hard', 'In a web browser like Chrome or Edge, what does pressing Ctrl + T do?', 'Turns off Wi-Fi', 'Opens a new browser tab', 'Closes the browser', 'Translates the page', 'b'),
