  (8, 'Application Software & OS', 'hard', 'On Windows, files ending in ".exe" (or ".apk" on Android) are what kind of files?', 'Family vacation photos', 'Spreadsheet charts', 'Application installer / executable program files (only run from trusted official sources!)', 'Plain text essays', 'c'),
  (8, 'Application Software & OS', 'hard', 'Before editing an important project presentation, why is naming files clearly like "Science_Poster_v2_Final.pptx" better than "asdf123.pptx"?', 'It changes slide colors automatically', 'Long names increase RAM', 'Computers refuse to save short names', 'Clear file names let you and your teammates find the right version in seconds without confusion', 'd'),
  (8, 'Web Browsing & Internet', 'easy', 'What is the website address typed at the top of a browser (like `https://mapleskhatauli.com`) commonly called?', 'Battery level', 'RAM address', 'PIN code', 'URL (Website Address)', 'd'),
